// Asteroid Dodge – minimal implementation
// Targets canvas with id "game" in the host HTML

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

// Player ship
const ship = {
  x: canvas.width / 2,
  y: canvas.height - 50,
  w: 30,
  h: 30,
  speed: 5,
  draw() {
    ctx.fillStyle = '#0ff';
    ctx.fillRect(this.x - this.w / 2, this.y - this.h / 2, this.w, this.h);
  }
};

let keys = {};
window.addEventListener('keydown', e => {keys[e.key] = true;});
window.addEventListener('keyup', e => {keys[e.key] = false;});

// Asteroids
let asteroids = [];
function spawnAsteroid() {
  const size = Math.random() * 30 + 20;
  asteroids.push({
    x: Math.random() * (canvas.width - size) + size / 2,
    y: -size,
    r: size / 2,
    speed: Math.random() * 2 + 1,
    draw() {
      ctx.fillStyle = '#999';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
      ctx.fill();
    }
  });
}
let spawnTimer = 0;

// Simple timer (seconds)
let timeLeft = 60; // 60‑second game
let lastSecond = Date.now();

function update(dt) {
  // Move ship
  if (keys['ArrowLeft']) ship.x -= ship.speed;
  if (keys['ArrowRight']) ship.x += ship.speed;
  if (keys['ArrowUp']) ship.y -= ship.speed;
  if (keys['ArrowDown']) ship.y += ship.speed;
  // Clamp inside canvas
  ship.x = Math.max(ship.w / 2, Math.min(canvas.width - ship.w / 2, ship.x));
  ship.y = Math.max(ship.h / 2, Math.min(canvas.height - ship.h / 2, ship.y));

  // Spawn asteroids
  spawnTimer += dt;
  if (spawnTimer > 0.5) { // every 0.5 s
    spawnAsteroid();
    spawnTimer = 0;
  }

  // Update asteroids
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.y += a.speed;
    // Remove off‑screen
    if (a.y - a.r > canvas.height) asteroids.splice(i, 1);
    // Collision detection (circle‑rect)
    const dx = Math.abs(a.x - ship.x);
    const dy = Math.abs(a.y - ship.y);
    if (dx > (ship.w / 2 + a.r) || dy > (ship.h / 2 + a.r)) continue;
    if (dx <= ship.w / 2 || dy <= ship.h / 2) {
      endGame();
      return;
    }
    const cornerDistSq = (dx - ship.w / 2) ** 2 + (dy - ship.h / 2) ** 2;
    if (cornerDistSq <= a.r ** 2) { endGame(); return; }
  }

  // Timer countdown
  const now = Date.now();
  if (now - lastSecond >= 1000) {
    timeLeft--;
    lastSecond = now;
    if (timeLeft <= 0) endGame();
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ship.draw();
  asteroids.forEach(a => a.draw());
  // HUD
  ctx.fillStyle = '#fff';
  ctx.font = '20px sans-serif';
  ctx.fillText('Time: ' + timeLeft, 10, 30);
}

let lastTime = 0;
let gameOver = false;
function loop(timestamp) {
  if (gameOver) return;
  const dt = (timestamp - lastTime) / 1000;
  lastTime = timestamp;
  update(dt);
  draw();
  requestAnimationFrame(loop);
}
function endGame() {
  gameOver = true;
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#f00';
  ctx.font = '40px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
}
requestAnimationFrame(loop);
